namespace WypozyczalniaSportowa.Domain.Pricing; public sealed class WeekendPricingStrategy : IPricingStrategy { public string Name => "Weekendowy (10% taniej w weekend)"; public decimal Calculate(decimal rate, RentalPeriod p) { decimal total = 0; for (var d = p.Start; d <= p.End; d = d.AddDays(1)) total += d.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday ? rate * .90m : rate; return total; } public override string ToString() => Name; }